function collect(modules){const wanted=new Set(modules),seen=new Set,groups=new Map;$$('[data-save-key]').forEach(f=>{const sec=f.closest('.course-section[data-module-number]');if(!sec)return;const m=Number(sec.dataset.moduleNumber);if(!wanted.has(m))return;if(f.type==='radio'){if(!f.checked||seen.has(f.name))return;seen.add(f.name)}else if(f.type==='checkbox'){if(!f.checked)return}else if(!String(f.value||'').trim())return;const a=answer(f);if(!a)return;const key=`${m}|${sec.id}`;if(!groups.has(key))groups.set(key,{module:m,sectionId:sec.id,title:clean(sec.querySelector('h2'))||sec.id,items:[]});groups.get(key).items.push({q:label(f,sec),a})});return[...groups.values()].sort((a,b)=>a.module-b.module||a.sectionId.localeCompare(b.sectionId,'pl',{numeric:true}))}
